package com.honorablemobile

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
class VideoLookReviewOwnershipTest {
 private val unsafe=Class.forName("sun.misc.Unsafe").getDeclaredField("theUnsafe").apply{isAccessible=true}.get(null)as sun.misc.Unsafe
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun fixture():Triple<HonorableVideoEditorActivity,AlertDialog,VideoLookReview>{val a=activity();val d=dialog();val r=VideoLookReview();r.open(d);set(a,"lookReviewRequest",r);set(a,"lookReviewDialog",d);set(a,"captionReviewDialogs",linkedSetOf(d));return Triple(a,d,r)}
 private fun perform(a:HonorableVideoEditorActivity,d:AlertDialog,r:VideoLookReview,review:VideoCaptionReviewState,action:(()->Unit)->Unit)=call(a,"performLookReview",d,r,review,action)as Boolean
 @Test fun successorSurvivesLatePredecessorDismiss(){val r=VideoLookReview();val old=Any();val next=Any();assertTrue(r.open(old));assertTrue(r.open(next));r.dismiss(old);assertTrue(r.owns(next));assertFalse(r.owns(old));r.dismiss(next);assertTrue(r.isClosed)}
 @Test fun approvalIsConsumedBeforeGuardAndOnlyOnce(){val r=VideoLookReview();val d=Any();r.open(d);var calls=0;assertTrue(r.execute(d,{assertFalse(r.owns(d));assertTrue(r.isExecuting(d))}){calls++});assertFalse(r.isExecuting(d));assertFalse(r.execute(d,{fail("guard")}){calls++});assertEquals(1,calls);assertFalse(r.open(Any()))}
 @Test fun failedGuardConsumesApprovalWithoutSideEffect(){val r=VideoLookReview();val d=Any();r.open(d);try{r.execute(d,{error("stale")}){fail("write")};fail("accepted")}catch(_:IllegalStateException){};assertTrue(r.isClosed);assertFalse(r.isExecuting(d))}
 @Test fun failureClearsExecutionPermission(){val r=VideoLookReview();val d=Any();r.open(d);try{r.execute(d,{}){error("IO")};fail("accepted")}catch(_:IllegalStateException){};assertFalse(r.isExecuting(d));assertTrue(r.isClosed)}
 @Test fun foreignStageCannotConsumeCurrent(){val r=VideoLookReview();val d=Any();r.open(d);assertFalse(r.execute(Any(),{fail("guard")}){fail("write")});assertTrue(r.owns(d))}
 @Test fun closeRevokesGuardWhileActionIsRunning(){val r=VideoLookReview();val d=Any();r.open(d);r.execute(d,{}){assertTrue(r.isExecuting(d));r.close();assertFalse(r.isExecuting(d))};assertTrue(r.isClosed)}
 @Test fun actualActivityExecutesGuardedActionOnce(){val(a,d,r)=fixture();val review=capture(a);var calls=0;var retained:(()->Unit)?=null;assertTrue(perform(a,d,r,review){guard->guard();retained=guard;calls++;guard()});assertEquals(1,calls);assertFalse(perform(a,d,r,review){calls++});try{retained!!();fail("guard survived") }catch(e:IllegalStateException){};assertEquals(1,calls)}
 @Test fun staleForegroundSourceDurationGenerationAndSessionCannotExecute(){for(flag in listOf("pause","source","duration","generation","mode","busy","recovery","analysis")){val(a,d,r)=fixture();val review=capture(a);when(flag){"pause"->set(a,"workspaceActive",false);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",5001L);"generation"->set(a,"captionReviewGeneration",review.generation+1);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"busy"->set(a,"saving",true);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));else->set(a,"analyzing",true)};assertFalse(flag,perform(a,d,r,review){fail("write")});assertFalse((get(a,"project")as VideoEditProject).canUndo)}}
 @Test fun oldDialogAndRequestCannotConsumeNewOwner(){val(a,old,r)=fixture();val review=capture(a);val newer=dialog();val next=VideoLookReview();next.open(newer);set(a,"lookReviewRequest",next);set(a,"lookReviewDialog",newer);set(a,"captionReviewDialogs",linkedSetOf(newer));assertFalse(perform(a,old,r,review){fail("write")});assertTrue(next.owns(newer));assertTrue(perform(a,newer,next,review){it()})}
 @Test fun hiddenAndUntrackedDialogsCannotWrite(){for(flag in listOf("hidden","untracked")){val(a,d,r)=fixture();val review=capture(a);if(flag=="hidden")showing(d,false)else set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());assertFalse(perform(a,d,r,review){fail("write")})}}
 @Test fun invalidNameAndDuplicatePrevalidationRemainRetryable(){val r=VideoLookReview();val d=Any();r.open(d);val look=NamedVideoColorLook("First",VideoGrade());val catalog=VideoColorLookCatalog(listOf(look));for(name in listOf("","first")){try{catalog.add(NamedVideoColorLook(name,VideoGrade()));fail("accepted")}catch(_:IllegalArgumentException){};assertTrue(r.owns(d))};assertEquals(2,catalog.add(NamedVideoColorLook("Second",VideoGrade())).looks.size);assertTrue(r.execute(d,{}){})}
 @Test fun changedOrDeletedRecordRefusesButUnrelatedAdditionsSurvive(){val look=NamedVideoColorLook("First",VideoGrade());val other=NamedVideoColorLook("Second",VideoGrade());val base=VideoColorLookCatalog(listOf(look));VideoLookReview.requireAvailable(base.add(other),look);assertEquals(listOf(other),base.add(other).remove(look).looks);for(catalog in listOf(VideoColorLookCatalog(),VideoColorLookCatalog(listOf(look.copy(grade=VideoGrade(exposure=.5f)))))){try{VideoLookReview.requireAvailable(catalog,look);fail("accepted stale")}catch(_:IllegalArgumentException){}};assertEquals(base,VideoColorLookCodec.decode(VideoColorLookCodec.encode(base)))}
 @Test fun approvedLookChangesOnlyGradeWithOneUndo(){val(a,d,r)=fixture();val review=capture(a);val p=get(a,"project")as VideoEditProject;val old=p.segments;val music=p.soundtrack;val look=NamedVideoColorLook("Warm",VideoGrade(warmth=.25f));assertTrue(perform(a,d,r,review){guard->guard();p.applyDraft(old.map{look.applyTo(it)},soundtrack=music)});assertEquals(old[0].copy(grade=look.grade),p.segments[0]);assertSame(music,p.soundtrack);assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo);assertFalse(perform(a,d,r,review){fail("revived")});assertTrue(p.canRedo)}
 @Test fun lifecycleClosesLeaseAndPausedEntryReturnsBeforeStorageOrWidgets(){val(a,d,r)=fixture();set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());call(a,"invalidateCaptionReviews");assertTrue(r.isClosed);assertNull(get(a,"lookReviewRequest"));assertNull(get(a,"lookReviewDialog"));for(flag in listOf("pause","busy","recovery")){val b=activity();when(flag){"pause"->set(b,"workspaceActive",false);"busy"->set(b,"saving",true);else->set(b,"recoveryBytes",byteArrayOf(1))};call(b,"savedColorLooks");assertNull(get(b,"lookReviewRequest"));assertNull(get(b,"captionReviewDialogs"))}}
}
